import {defineTool} from '@deepseek-ai/dsh-tools';
import {readFileSync,realpathSync} from 'node:fs';
import {registerCapability} from '../capability-sdk/adapter.js';
import {call} from '../natural-data/index.js';
import {installRecovery} from '../natural-data/recovery.js';
import {installAnswerGuard} from '../natural-data/answer-guard.js';
import {installMixedDelivery} from '../natural-data/mixed-delivery.js';
import {installPurposeQuestions} from '../natural-data/intent-questions.js';
export const name='natural-capabilities';
export const inject=['tools','systemPrompt'];
const manifests=['capability.json','analysis-capability.json','work-capability.json','knowledge-capability.json'].map(file=>JSON.parse(readFileSync(new URL('./manifests/'+file,import.meta.url),'utf8')));
export function apply(ctx,config={}){
  const selected=new Set(config.capabilities||manifests.map(m=>m.id));
  const active=manifests.filter(m=>selected.has(m.id));
  const policies=new Map();
  ctx.on('agent/pre-step',async({agent,signal},next)=>{
    if(signal.aborted)return next();
    const project=realpathSync(agent.session.header.cwd);
    const policy=await call('policy',project,{},'',signal,agent.id);
    const previous=policies.get(agent.id);previous?.dispose();
    const deny=active.flatMap(m=>policy.states[m.id]==='enabled'?[]:m.operations.filter(o=>!(policy.states[m.id]==='history'&&['read','inspect','export'].includes(o.name))).map(o=>m.id+'_'+o.name));
    const dispose=deny.length?agent.ctx.tools.restrict({deny}):()=>{};
    const promptDispose=agent.ctx.systemPrompt.section({name:'natural-work:enabled-capabilities',order:11000,text:'宿主能力配置版本 '+policy.revision+'；当前状态：'+JSON.stringify(policy.states)+'。仅使用已启用的工具；能力关闭不是数据为零。'});
    policies.set(agent.id,{dispose:()=>{dispose();promptDispose();},revision:policy.revision});
    return next();
  },{prepend:true});
  ctx.on('agent/disposed',({agent})=>{policies.get(agent.id)?.dispose();policies.delete(agent.id);});
  installRecovery(ctx);
  installAnswerGuard(ctx);
  installPurposeQuestions(ctx);
  installMixedDelivery(ctx);
  for(const manifest of active) registerCapability(ctx,{
    manifest, defineTool,
    prompt:manifest.id==='data'?readFileSync(new URL('../natural-data/SKILL.md',import.meta.url),'utf8'):'能力工序 '+manifest.id+'：复用同一Harness会话和权限，按输入与输出合约执行。',
    context(exec){
      const cwd=exec.agent?.session.header.cwd;
      if(!cwd)throw Error('问数工具必须在已选择工作区的 Harness 会话中调用。');
      const events=exec.agent.session.snapshotEvents();
      const users=events.filter(e=>e.type==='user/message'&&e.data.source?.kind==='user');
      const first=users.length===1?users[0].data:null;
      const text=first?.content?.filter(x=>x.type==='text').map(x=>x.text).join('\n')||'';
      const materialOnly=Boolean(first)&&(!text.trim()||(!/[?？查问看统算分析对比比较展示多少如何怎么请帮解释整理写]/.test(text)&&(text.split('\n').filter(x=>x.trim()).length>1||/^[\d\s.,，、；;]+$/.test(text))));
      const latest=users.at(-1);
      const user_text=latest?.data.content?.filter(x=>x.type==='text').map(x=>x.text).join('\n')||'';
      const askIds=new Set(events.filter(e=>e.seq>(latest?.seq??0)&&e.type==='tool/call'&&e.data.name==='ask_user_question').map(e=>e.data.callId));
      const confirmation=events.filter(e=>e.type==='tool/result'&&askIds.has(e.data.message.source?.callId)&&!e.data.message.isError).flatMap(e=>e.data.message.content||[]).filter(x=>x.type==='text').map(x=>{try{return JSON.parse(x.text).answers.map(a=>a.custom||a.selected?.join(' ')||'').join('\n');}catch{return '';}}).join('\n');
      const client_time_zone=latest?.data.source?.clientTimeZone||Intl.DateTimeFormat().resolvedOptions().timeZone;
      return {host_evidence:{user_text,confirmation,user_ref:latest?.data.id,client_time_zone},session:exec.agent.id,project:realpathSync(cwd),key:`${exec.agent.id}:${exec.callId}`,materialOnly};
    },
    invoke:(op,args,scope,signal)=>{
      if(scope.materialOnly&&manifest.id==='data')throw Error('NEEDS_INTENT: 用户仅提供材料，尚未要求查数。请询问用途（解释指标、整理文档或分析数据），不要只询问查询期间。');
      return call('capabilities/'+manifest.id+'/'+op,scope.project,args,scope.key,signal,scope.session,scope.host_evidence);
    },
    cancel(op,scope,args){if(manifest.id==='data'&&['query','report'].includes(op))void call('cancel',scope.project,{},args.plan_ref?'bound:'+args.plan_ref:scope.key,undefined,scope.session).catch(()=>{});},
    decorate(op,value,scope){
      if(value.result_ref){
        const query=new URLSearchParams({project:value.execution_scope||scope.project,result_ref:value.result_ref});
        value.view_url='/natural-data/view?'+query;
        if(op==='export')value.download_url='/natural-data/api/export?'+query;
      }
      return value;
    }
  });
}
